insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('deu-3-25','deu','신명기',3,25,'구하옵나니 나를 건너가게 하사 요단 저쪽에 있는 아름다운 땅, 아름다운 산과 레바논을 보게 하옵소서 하되',5001),
('deu-3-26','deu','신명기',3,26,'여호와께서 너희 때문에 내게 진노하사 내 말을 듣지 아니하시고 내게 이르시기를 그만해도 족하니 이 일로 다시 내게 말하지 말라',5002),
('deu-3-27','deu','신명기',3,27,'너는 비스가 산 꼭대기에 올라가서 눈을 들어 동서남북을 바라고 네 눈으로 그 땅을 바라보라 너는 이 요단을 건너지 못할 것임이니라',5003),
('deu-3-28','deu','신명기',3,28,'너는 여호수아에게 명령하고 그를 담대하게 하며 그를 강하게 하라 그는 이 백성을 거느리고 건너가서 네가 볼 땅을 그들이 기업으로 얻게 하리라 하셨느니라',5004),
('deu-3-29','deu','신명기',3,29,'그 때에 우리가 벳브올 맞은편 골짜기에 거주하였느니라',5005),
('deu-4-1','deu','신명기',4,1,'이스라엘아 이제 내가 너희에게 가르치는 규례와 법도를 듣고 준행하라 그리하면 너희가 살 것이요 너희 조상의 하나님 여호와께서 너희에게 주시는 땅에 들어가서 그것을 얻게 되리라',5006),
('deu-4-2','deu','신명기',4,2,'내가 너희에게 명령하는 말을 너희는 가감하지 말고 내가 너희에게 내리는 너희 하나님 여호와의 명령을 지키라',5007),
('deu-4-3','deu','신명기',4,3,'여호와께서 바알브올의 일로 말미암아 행하신 바를 너희가 눈으로 보았거니와 바알브올을 따른 모든 사람을 너희의 하나님 여호와께서 너희 가운데에서 멸망시키셨으되',5008),
('deu-4-4','deu','신명기',4,4,'오직 너희의 하나님 여호와께 붙어 떠나지 않은 너희는 오늘까지 다 생존하였느니라',5009),
('deu-4-5','deu','신명기',4,5,'내가 나의 하나님 여호와께서 명령하신 대로 규례와 법도를 너희에게 가르쳤나니 이는 너희가 들어가서 기업으로 차지할 땅에서 그대로 행하게 하려 함인즉',5010),
('deu-4-6','deu','신명기',4,6,'너희는 지켜 행하라 이것이 여러 민족 앞에서 너희의 지혜요 너희의 지식이라 그들이 이 모든 규례를 듣고 이르기를 이 큰 나라 사람은 과연 지혜와 지식이 있는 백성이로다 하리라',5011),
('deu-4-7','deu','신명기',4,7,'우리 하나님 여호와께서 우리가 그에게 기도할 때마다 우리에게 가까이 하심과 같이 그 신이 가까이 함을 얻은 큰 나라가 어디 있느냐',5012),
('deu-4-8','deu','신명기',4,8,'오늘 내가 너희에게 선포하는 이 율법과 같이 그 규례와 법도가 공의로운 큰 나라가 어디 있느냐',5013),
('deu-4-9','deu','신명기',4,9,'오직 너는 스스로 삼가며 네 마음을 힘써 지키라 그리하여 네가 눈으로 본 그 일을 잊어버리지 말라 네가 생존하는 날 동안에 그 일들이 네 마음에서 떠나지 않도록 조심하라 너는 그 일들을 네 아들들과 네 손자들에게 알게 하라',5014),
('deu-4-10','deu','신명기',4,10,'네가 호렙 산에서 네 하나님 여호와 앞에 섰던 날에 여호와께서 내게 이르시기를 나에게 백성을 모으라 내가 그들에게 내 말을 들려주어 그들이 세상에 사는 날 동안 나를 경외함을 배우게 하며 그 자녀에게 가르치게 하리라 하시매',5015),
('deu-4-11','deu','신명기',4,11,'너희가 가까이 나아와서 산 아래에 서니 그 산에 불이 붙어 불길이 충천하고 어둠과 구름과 흑암이 덮였는데',5016),
('deu-4-12','deu','신명기',4,12,'여호와께서 불길 중에서 너희에게 말씀하시되 음성뿐이므로 너희가 그 말소리만 듣고 형상은 보지 못하였느니라',5017),
('deu-4-13','deu','신명기',4,13,'여호와께서 그의 언약을 너희에게 반포하시고 너희에게 지키라 명령하셨으니 곧 십계명이며 두 돌판에 친히 쓰신 것이라',5018),
('deu-4-14','deu','신명기',4,14,'그 때에 여호와께서 내게 명령하사 너희에게 규례와 법도를 교훈하게 하셨나니 이는 너희가 거기로 건너가 받을 땅에서 행하게 하려 하심이니라',5019),
('deu-4-15','deu','신명기',4,15,'여호와께서 호렙 산 불길 중에서 너희에게 말씀하시던 날에 너희가 어떤 형상도 보지 못하였은즉 너희는 깊이 삼가라',5020),
('deu-4-16','deu','신명기',4,16,'그리하여 스스로 부패하여 자기를 위해 어떤 형상대로든지 우상을 새겨 만들지 말라 남자의 형상이든지, 여자의 형상이든지,',5021),
('deu-4-17','deu','신명기',4,17,'땅 위에 있는 어떤 짐승의 형상이든지, 하늘을 나는 날개 가진 어떤 새의 형상이든지,',5022),
('deu-4-18','deu','신명기',4,18,'땅 위에 기는 어떤 곤충의 형상이든지, 땅 아래 물 속에 있는 어떤 어족의 형상이든지 만들지 말라',5023),
('deu-4-19','deu','신명기',4,19,'또 그리하여 네가 하늘을 향하여 눈을 들어 해와 달과 별들, 하늘 위의 모든 천체 곧 너희의 하나님 여호와께서 천하 만민을 위하여 배정하신 것을 보고 미혹하여 그것에 경배하며 섬기지 말라',5024),
('deu-4-20','deu','신명기',4,20,'여호와께서 너희를 택하시고 너희를 쇠 풀무불 곧 애굽에서 인도하여 내사 자기 기업의 백성을 삼으신 것이 오늘과 같아도',5025),
('deu-4-21','deu','신명기',4,21,'여호와께서 너희로 말미암아 내게 진노하사 내게 요단을 건너지 못하며 네 하나님 여호와께서 네게 기업으로 주신 그 아름다운 땅에 들어가지 못하게 하리라고 맹세하셨은즉',5026),
('deu-4-22','deu','신명기',4,22,'나는 이 땅에서 죽고 요단을 건너지 못하려니와 너희는 건너가서 그 아름다운 땅을 얻으리니',5027),
('deu-4-23','deu','신명기',4,23,'너희는 스스로 삼가 너희의 하나님 여호와께서 너희와 세우신 언약을 잊지 말고 네 하나님 여호와께서 금하신 어떤 형상의 우상도 조각하지 말라',5028),
('deu-4-24','deu','신명기',4,24,'네 하나님 여호와는 소멸하는 불이시요 질투하시는 하나님이시니라',5029),
('deu-4-25','deu','신명기',4,25,'네가 그 땅에서 아들을 낳고 손자를 얻으며 오래 살 때에 만일 스스로 부패하여 무슨 형상의 우상이든지 조각하여 네 하나님 여호와 앞에 악을 행함으로 그의 노를 일으키면',5030),
('deu-4-26','deu','신명기',4,26,'내가 오늘 천지를 불러 증거를 삼노니 너희가 요단을 건너가서 얻는 땅에서 속히 망할 것이라 너희가 거기서 너희의 날이 길지 못하고 전멸될 것이니라',5031),
('deu-4-27','deu','신명기',4,27,'여호와께서 너희를 여러 민족 중에 흩으실 것이요 여호와께서 너희를 쫓아 보내실 그 여러 민족 중에 너희의 남은 수가 많지 못할 것이며',5032),
('deu-4-28','deu','신명기',4,28,'너희는 거기서 사람의 손으로 만든 바 보지도 못하며 듣지도 못하며 먹지도 못하며 냄새도 맡지 못하는 목석의 신들을 섬기리라',5033),
('deu-4-29','deu','신명기',4,29,'그러나 네가 거기서 네 하나님 여호와를 찾게 되리니 만일 마음을 다하고 뜻을 다하여 그를 찾으면 만나리라',5034),
('deu-4-30','deu','신명기',4,30,'이 모든 일이 네게 임하여 환난을 당하다가 끝날에 네가 네 하나님 여호와께로 돌아와서 그의 말씀을 청종하리니',5035),
('deu-4-31','deu','신명기',4,31,'네 하나님 여호와는 자비하신 하나님이심이라 그가 너를 버리지 아니하시며 너를 멸하지 아니하시며 네 조상들에게 맹세하신 언약을 잊지 아니하시리라',5036),
('deu-4-32','deu','신명기',4,32,'네가 있기 전 하나님이 사람을 세상에 창조하신 날부터 지금까지 지나간 날을 상고하여 보라 하늘 이 끝에서 저 끝까지 이런 큰 일이 있었느냐 이런 일을 들은 적이 있었느냐',5037),
('deu-4-33','deu','신명기',4,33,'어떤 국민이 불 가운데에서 말씀하시는 하나님의 음성을 너처럼 듣고 생존하였느냐',5038),
('deu-4-34','deu','신명기',4,34,'어떤 신이 와서 시험과 이적과 기사와 전쟁과 강한 손과 편 팔과 크게 두려운 일로 한 민족을 다른 민족에게서 인도하여 낸 일이 있느냐 이는 다 너희의 하나님 여호와께서 애굽에서 너희를 위하여 너희의 목전에서 행하신 일이라',5039),
('deu-4-35','deu','신명기',4,35,'이것을 네게 나타내심은 여호와는 하나님이시요 그 외에는 다른 신이 없음을 네게 알게 하려 하심이니라',5040),
('deu-4-36','deu','신명기',4,36,'여호와께서 너를 교훈하시려고 하늘에서부터 그의 음성을 네게 듣게 하시며 땅에서는 그의 큰 불을 네게 보이시고 네가 불 가운데서 나오는 그의 말씀을 듣게 하셨느니라',5041),
('deu-4-37','deu','신명기',4,37,'여호와께서 네 조상들을 사랑하신 고로 그 후손인 너를 택하시고 큰 권능으로 친히 인도하여 애굽에서 나오게 하시며',5042),
('deu-4-38','deu','신명기',4,38,'너보다 강대한 여러 민족을 네 앞에서 쫓아내고 너를 그들의 땅으로 인도하여 들여서 그것을 네게 기업으로 주려 하심이 오늘과 같으니라',5043),
('deu-4-39','deu','신명기',4,39,'그런즉 너는 오늘 위로 하늘에나 아래로 땅에 오직 여호와는 하나님이시요 다른 신이 없는 줄을 알아 명심하고',5044),
('deu-4-40','deu','신명기',4,40,'오늘 내가 네게 명령하는 여호와의 규례와 명령을 지키라 너와 네 후손이 복을 받아 네 하나님 여호와께서 네게 주시는 땅에서 한 없이 오래 살리라',5045),
('deu-4-41','deu','신명기',4,41,'그 때에 모세가 요단 이쪽 해 돋는 쪽에서 세 성읍을 구별하였으니',5046),
('deu-4-42','deu','신명기',4,42,'이는 과거에 원한이 없이 부지중에 살인한 자가 그 곳으로 도피하게 하기 위함이며 그 중 한 성읍으로 도피한 자가 그의 생명을 보전하게 하기 위함이라',5047),
('deu-4-43','deu','신명기',4,43,'하나는 광야 평원에 있는 베셀이라 르우벤 지파를 위한 것이요 하나는 길르앗 라못이라 갓 지파를 위한 것이요 하나는 바산 골란이라 므낫세 지파를 위한 것이었더라',5048),
('deu-4-44','deu','신명기',4,44,'모세가 이스라엘 자손에게 선포한 율법은 이러하니라',5049),
('deu-4-45','deu','신명기',4,45,'이스라엘 자손이 애굽에서 나온 후에 모세가 증언과 규례와 법도를 선포하였으니',5050),
('deu-4-46','deu','신명기',4,46,'요단 동쪽 벳브올 맞은편 골짜기에서 그리하였더라 이 땅은 헤스본에 사는 아모리 족속의 왕 시혼에게 속하였더니 모세와 이스라엘 자손이 애굽에서 나온 후에 그를 쳐서 멸하고',5051),
('deu-4-47','deu','신명기',4,47,'그 땅을 기업으로 얻었고 또 바산 왕 옥의 땅을 얻었으니 그 두 사람은 아모리 족속의 왕으로서 요단 이쪽 해 돋는 쪽에 살았으며',5052),
('deu-4-48','deu','신명기',4,48,'그 얻은 땅은 아르논 골짜기 가장자리의 아로엘에서부터 시온 산 곧 헤르몬 산까지요',5053),
('deu-4-49','deu','신명기',4,49,'요단 이쪽 곧 그 동쪽 온 아라바니 비스가 기슭 아래 아라바의 바다까지이니라',5054),
('deu-5-1','deu','신명기',5,1,'모세가 온 이스라엘을 불러 그들에게 이르되 이스라엘아 오늘 내가 너희의 귀에 말하는 규례와 법도를 듣고 그것을 배우며 지켜 행하라',5055),
('deu-5-2','deu','신명기',5,2,'우리 하나님 여호와께서 호렙 산에서 우리와 언약을 세우셨나니',5056),
('deu-5-3','deu','신명기',5,3,'이 언약은 여호와께서 우리 조상들과 세우신 것이 아니요 오늘 여기 살아 있는 우리 곧 우리와 세우신 것이라',5057),
('deu-5-4','deu','신명기',5,4,'여호와께서 산 위 불 가운데에서 너희와 대면하여 말씀하시매',5058),
('deu-5-5','deu','신명기',5,5,'그 때에 너희가 불을 두려워하여 산에 오르지 못하므로 내가 여호와와 너희 중간에 서서 여호와의 말씀을 너희에게 전하였노라 여호와께서 이르시되',5059),
('deu-5-6','deu','신명기',5,6,'나는 너를 애굽 땅, 종 되었던 집에서 인도하여 낸 네 하나님 여호와라',5060),
